#!/usr/bin/env python3
"""Publish measured campaign results only after the independent delivery audit."""
import json,os
from pathlib import Path
from common import ROOT,sha256,save

def main():
    os.chdir(ROOT);audit=json.loads(Path('bench/cpu-next-delivery-check.json').read_text());assert audit['status']=='passed'
    for name,digest in audit['reports'].items():assert sha256('bench/cpu-next-'+name+'.json')==digest
    batch=json.loads(Path('bench/cpu-next-batches.json').read_text());scaling=json.loads(Path('bench/cpu-next-scaling.json').read_text());large=json.loads(Path('bench/cpu-next-large.json').read_text())
    promoted=audit['decision']=='promote';h=audit['effects']['human'];workers=batch['worker_selection']['selected_workers']
    lines=['## Final measured decision','',('Accept v0.3.3: widen K64 forward/backward and eight-site count blocks to 32 independent destinations.' if promoted else 'Retain v0.3.2: the exact candidate did not establish sufficient complete-workload benefit.'),'',f"The candidate SHA256 is `{audit['candidate_sha256']}`. Frozen v0.3.2 SHA256 is `{audit['baseline_sha256']}`. Baseline source commit is 4ab9ff5; exact candidate source, Rust 1.90.0 compiler/profile and linked libraries are in bench/cpu-next-build.json. The milestone commit contains the implementation, reproducible candidate generators, proofs, tests and measurements together.",'',f"Complete HG001 chromosome 22 batches use all 30 fixed bootstraps, K64 and N30. The repeated paired comparison uses **{workers} workers** with affinity `{batch['affinity']}` for both binaries. There is one warmup and three alternating measured pairs per workload. Because the first two human pairs disagreed, a fixed second block added one warmup and three opposite-order pairs; the human row pools all six measured pairs. Human median wall reduction is **{h['wall_reduction_percent']:.2f}%**, throughput ratio **{h['throughput_ratio']:.4f}x**, and median total CPU reduction **{h['cpu_reduction_percent']:.2f}%**. These are shared-host measurements on the Intel Core i5-12600K, not guarantees on other systems. Ranges overlap; six paired batches support a limited measured comparison, not a formal significance claim.",'','| Workload | Binary | Wall median [min, max], s | CPU median, s | Sampled peak RSS median, MiB |','|---|---|---:|---:|---:|']
    batch['summary']['human']=audit['pooled_human_summary']
    for case,results in batch['summary'].items():
        for label,v in results.items():
            w=v['wall_seconds'];lines.append(f"| {case} | {label} | {w['median']:.3f} [{w['minimum']:.3f}, {w['maximum']:.3f}] | {v['cpu_seconds']['median']:.3f} | {v['sampled_aggregate_rss_kib']['median']/1024:.1f} |")
    lines+=['','All six human paired effects are retained below; positive values mean the candidate used less time. No run is dropped for being slow.','','| Block | Pair | Wall reduction % | CPU reduction % |','|---|---:|---:|---:|']
    for r in audit['paired_human_effects']:lines.append(f"| {r['block']} | {r['repeat']} | {r['wall_reduction_percent']:.2f} | {r['cpu_reduction_percent']:.2f} |")
    lines+=['','K23 rows are controls: these changes specialize only K64. Small K23 timing differences and overlapping ranges do not establish an improvement at other state counts. Allocation and dispatch experiments did not explain the earlier minor K23 slowdown; those production paths remain unchanged. No resident-memory reduction is claimed. RSS is sampled every 20 ms for human batches and 10 ms for synthetic batches, excludes the controller, and is a lower bound on peak live-process RSS.','', '### Worker screen','', 'Each row below is one complete 30-bootstrap screen, not a repeated scaling estimate. The 10-worker case uses one logical CPU per physical core; 8 and 16 use all allowed CPUs. Worker count and affinity therefore change together. The common confirmation configuration was selected by the lowest mean of both releases\' screen wall times, then tested again on fresh repeated batches.','', '| Workers | Binary | Wall seconds | Total CPU seconds |','|---:|---|---:|---:|']
    for r in scaling['runs']:lines.append(f"| {r['workers']} | {r['label']} | {r['wall_seconds']:.3f} | {r['cpu_seconds']:.3f} |")
    lines+=['','### Larger held-out chromosome','', 'The full HG002 GRCh38 chromosome 1 fixture has 2,489,565 bins and stays one continuous HMM record. All three full N30 fits are finite, and both Rust outputs exactly match pinned vanilla C apart from the version line. Single descriptive runs follow; **they are not repeated speed estimates**.','', '| Binary | Wall seconds | Peak RSS, MiB |','|---|---:|---:|']
    for r in large['runs']:lines.append(f"| {r['label']} | {r['wall_seconds']:.3f} | {r['peak_rss_kib']/1024:.1f} |")
    lines+=['','This is one chromosome, not a whole genome. Fifty upstream splitfa blocks and 30 fixed seeds are prepared for future HG002 bootstraps; those 30 fits were **not run**. The repeated acceptance workload remains HG001. Raw public human data are local ignored files and are not redistributed.','', '### Exactness, reproduction and limitations','',f"All 35 debug and 35 release unit tests pass, as do {audit['regression_cases']} complete dense/CPU/scalar regression cases with ordered intermediate snapshots; 66 extended cases (39 finite, 27 reference-pathology controls); scheduler/cache checks; and 38 CLI/dispatch checks. Assembly inspection has zero FMA and horizontal-reduction instructions. The audit regenerates all six experiment source variants from the pinned baseline and verifies every source hash.",'',f"The delivery audit rechecks **{audit['total_outputs_rechecked']} outputs**: 12 profile outputs, 72 isolated-screen outputs, 12 combination outputs, 180 worker-screen outputs, 240 confirmation outputs, 720 primary batch outputs, two HG001 unsplit outputs and three HG002 unsplit outputs. All 720 primary batch outputs, 240 confirmation outputs and 180 worker-screen outputs exactly match retained C references. Every bootstrap draw is independently replayed; no seed, repeated block or pathological reference result is removed. All 480 human primary/confirmation outputs are finite; original/model-based synthetic batches retain three/one pathological replicates respectively.",'', 'Production changes are confined to crates/psmc-cpu/src/simd.rs and version metadata in Cargo.toml, Cargo.lock and the CLI. Benchmark scripts/reports, this derivation and EXECPLAN.md record the campaign. Dense arithmetic, K23 kernels, the statistical model, optimizer, grids, counts, missingness, input boundaries and task queue are unchanged. No new dependency or architecture requirement is introduced. Runtime AVX selection and scalar fallback remain.','', 'Commands actually run are retained with hashes in the JSON reports. Reproduction entry points (new raw directories are required to avoid overwriting evidence):','', '```bash','python3 bench/cpu_next_fetch.py','python3 bench/cpu_next_hg002.py','python3 bench/cpu_next_profile.py','python3 bench/cpu_next_candidates.py build','python3 bench/cpu_next_candidates.py screen','python3 bench/cpu_next_combine.py','python3 bench/cpu_next_gates.py','python3 bench/cpu_next_large.py --candidate target/release/psmc-rs','python3 bench/cpu_next_scaling.py --candidate target/release/psmc-rs','python3 bench/cpu_next_batches.py --candidate target/release/psmc-rs','python3 bench/cpu_next_confirm.py',f"python3 bench/cpu_next_audit.py --decision {audit['decision']}",'python3 bench/cpu_next_report.py','```','', 'Profile instrumentation and candidate generators are baseline-specific; run their preparation from v0.3.2 as recorded. Final release gates use the accepted candidate source. Published executable copying is performed only after checking the measured decision. Raw evidence stays in ignored work/cpu-next* and the legacy validation directories. Earlier releases, archives and reports remain intact.','', 'ARM/NEON, GPU, whole-genome bootstrap throughput and the user\'s own data remain not_run. The 10x target remains unproven. No renewed whole-batch C speed ratio is claimed: canonical C outputs were reused for HG001, while HG002 has only one new C fit. Hardware counters are unavailable on this host; the profile uses disposable CPU-time instrumentation.','', 'Next permitted milestone: whole-genome or user-workload validation and profiling before another optimization campaign. This campaign supports a small additional CPU gain on the measured workload, not a claim that all possible CPU optimization has been exhausted.']
    lines+=['','The confirmation decision rule was recorded before its measurements: at least 2% pooled median human wall reduction, lower median CPU time, and positive paired effects in at least four of six comparisons for each metric. It is a practical release rule, not a statistical significance claim. '+('All four conditions passed.' if promoted else 'At least one condition failed; the threshold was not met.')]
    if not promoted:
        lines=[line.replace('Production changes are confined to crates/psmc-cpu/src/simd.rs and version metadata in Cargo.toml, Cargo.lock and the CLI.', 'The experimental changes were confined to crates/psmc-cpu/src/simd.rs and version metadata. Production source and executable are restored exactly to v0.3.2; the candidate remains in frozen gate evidence.').replace('Final release gates use the accepted candidate source.', 'Final compatibility gates used the provisional candidate source before the no-promotion decision.').replace('This campaign supports a small additional CPU gain on the measured workload, not a claim that all possible CPU optimization has been exhausted.', 'This campaign does not meet its predeclared release threshold. It does not establish that all possible CPU optimization has been exhausted.') for line in lines]
    path=Path('docs/cpu-next-optimization.md');prefix=path.read_text().split('\n## Final measured decision')[0];prefix=prefix.replace('Pending measured screens, larger-input validation, scaling and delivery audit.','The completed decision and measured evidence appear below.');path.write_text(prefix+'\n\n'+'\n'.join(lines)+'\n')
    save('bench/cpu-next-report-check.json',dict(status='passed',report_sha256=sha256(path),delivery_audit_sha256=sha256('bench/cpu-next-delivery-check.json'),runner_sha256=sha256(__file__)))
if __name__=='__main__':main()
